fabric_connector.IntentFabricConnector.resolve_tier:
def resolve_tier(self, intent: IntentCategory | str) -> str:
    """Détermine le palier requis pour une intention donnée."""
    if isinstance(intent, str):
        try:
            intent = IntentCategory(intent)
        except ValueError:
            return ModelTier.FAST.value
    return INTENT_TIER_MAP.get(intent, ModelTier.FAST.value)

fabric.AutonomousModelFabric.activate_qualified:
def activate_qualified(self, qualification_results: list[dict[str, Any]], exclusive_per_tier: bool=True) -> list[dict[str, Any]]:
    provider_rank = {'groq': 0, 'gemini': 1, 'openrouter': 2, 'litellm': 99}
    valid_tiers = {'FAST', 'MID', 'HEAVY'}
    transitions: list[dict[str, Any]] = []
    qualified_by_tier: dict[str, list[dict[str, Any]]] = {}
    for result in qualification_results:
        provider = str(result.get('provider', '')).lower()
        model_id = str(result.get('model_id', ''))
        qualified = bool(result.get('qualified', False))
        tier = str(result.get('tier', 'UNQUALIFIED')).upper()
        entry = self.registry.get(provider, model_id)
        if entry is None:
            print(f'[WARN] Activation ignorée : {provider}/{model_id} absent du registre.')
            continue
        if not qualified or tier not in valid_tiers:
            self.transition(provider=provider, model_id=model_id, new_state=ModelLifecycle.QUARANTINED.value, actor='activate_qualified', reason=f'Non qualifié ou tier invalide: {tier}', new_tier='UNQUALIFIED')
            transitions.append({'model': f'{provider}/{model_id}', 'old_state': 'QUALIFYING', 'new_state': ModelLifecycle.QUARANTINED.value, 'tier': 'UNQUALIFIED'})
            continue
        qualified_by_tier.setdefault(tier, []).append(result)
    winners: dict[str, dict[str, Any]] = {}
    for tier, candidates in qualified_by_tier.items():
        winners[tier] = min(candidates, key=lambda candidate: (-float(candidate.get('score', 0.0)), float(candidate.get('latency_ms', float('inf'))), provider_rank.get(str(candidate.get('provider', '')).lower(), 999), str(candidate.get('model_id', '')).lower()))
    for tier, candidates in qualified_by_tier.items():
        winner = winners[tier]
        for candidate in candidates:
            if candidate is winner:
                continue
            c_provider = str(candidate['provider']).lower()
            c_model_id = str(candidate['model_id'])
            c_entry = self.registry.get(c_provider, c_model_id)
            if c_entry is None:
                continue
            self.transition(provider=c_provider, model_id=c_model_id, new_state=ModelLifecycle.SUPERSEDED.value, actor='activate_qualified', reason=f'Éclipsé par le gagnant du tier {tier}', new_tier=tier)
            transitions.append({'model': f'{c_provider}/{c_model_id}', 'old_state': 'QUALIFIED', 'new_state': ModelLifecycle.SUPERSEDED.value, 'tier': tier})
    for tier, winner in winners.items():
        provider = str(winner['provider']).lower()
        model_id = str(winner['model_id'])
        entry = self.registry.get(provider, model_id)
        if entry is None:
            continue
        if exclusive_per_tier:
            for existing in self.registry.all():
                if existing.lifecycle == ModelLifecycle.ACTIVE.value and existing.tier == tier and (existing is not entry):
                    self.transition(provider=existing.provider.lower(), model_id=existing.model_id, new_state=ModelLifecycle.SUPERSEDED.value, actor='activate_qualified', reason=f'Remplacé par le nouveau gagnant ACTIVE du tier {tier}', new_tier=tier)
                    transitions.append({'model': f'{existing.provider}/{existing.model_id}', 'old_state': 'ACTIVE', 'new_state': ModelLifecycle.SUPERSEDED.value, 'tier': tier})
        self.transition(provider=provider, model_id=model_id, new_state=ModelLifecycle.ACTIVE.value, actor='activate_qualified', reason=f"Élu gagnant du tier {tier} (score: {winner.get('score')})", new_tier=tier)
        entry.qualification_score = float(winner.get('score', 0.0))
        entry.latency_ms = float(winner.get('latency_ms', 0.0))
        entry.last_verified = time.time()
        self.registry.save()
        transitions.append({'model': f'{provider}/{model_id}', 'old_state': 'QUALIFIED', 'new_state': ModelLifecycle.ACTIVE.value, 'tier': tier})
    self.registry.save()
    return transitions

fabric.AutonomousModelFabric._sync_router_with_:
def _sync_router_with_registry(self) -> None:
    """
        FAIL-CLOSED Synchronization (Canonique):
        Extrait strictement les modèles du ModelRegistry dont l'état de cycle de vie est ACTIVE.
        Exclut immédiatement tout modèle DISCOVERED, CANDIDATE, QUALIFIED, QUARANTINED, SUPERSEDED ou RETIRED.
        """
    active_models = []
    try:
        records = []
        if hasattr(self.registry, '_models') and isinstance(self.registry._models, dict):
            records = self.registry._models.values()
        elif hasattr(self.registry, 'all') and callable(self.registry.all):
            records = self.registry.all()
        for entry in records:
            lifecycle = str(getattr(entry, 'lifecycle', 'DISCOVERED')).upper()
            if lifecycle == 'ACTIVE':
                provider = str(getattr(entry, 'provider', 'openai')).lower()
                model_id = str(getattr(entry, 'model_id', 'gpt-4'))
                tier = str(getattr(entry, 'tier', 'FAST') or 'FAST').upper()
                deployment_dict = {'model_name': tier, 'litellm_params': {'model': f'{provider}/{model_id}', 'custom_llm_provider': provider}, 'model_info': {'id': f'{provider}_{model_id}', 'base_model': model_id, 'lifecycle': 'ACTIVE'}}
                active_models.append(deployment_dict)
    except Exception as e:
        print(f'[FAIL-CLOSED CRITICAL ERROR] Synchronisation active échouée : {e}')
        active_models = []
    if hasattr(self, 'router') and self.router is not None:
        if hasattr(self.router, 'set_model_list'):
            try:
                self.router.set_model_list(active_models)
            except Exception:
                self.router.model_list = active_models
        else:
            self.router.model_list = active_models
